// Environment readiness check for the workbench.
//
// Answers one question: everything the 19 bundled templates need is actually on
// this machine — node packages, model files, working ComfyUI, built server?
//
// Reads docs/DEPENDENCIES.json (generated by audit-template-deps.mjs) as the source
// of truth rather than keeping its own list, so adding a template cannot silently
// fall out of the check.
//
// Usage:
//   node scripts/check-environment.mjs           # 人读
//   node scripts/check-environment.mjs --json    # 机器读（控制台 / API 用）
//   node scripts/check-environment.mjs --quiet   # 只输出结论行
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

const ROOT = resolve(process.argv[1], '../..');
const JSON_MODE = process.argv.includes('--json');
const QUIET = process.argv.includes('--quiet');

const checks = [];
const add = (id, label, status, detail, hint) => {
  checks.push({ id, label, status, detail, hint });
};

// ── 配置
const configPath = join(ROOT, 'data', 'comfyui.config.json');
let config = {};
try {
  config = JSON.parse(readFileSync(configPath, 'utf8'));
} catch {
  // 缺失下面会单独报
}

const baseUrl = String(config.baseUrl ?? 'http://127.0.0.1:8188').replace(/\/+$/, '');
const isLocalComfy =
  /\/\/(127\.0\.0\.1|localhost|\[::1\])(:|\/|$)/.test(baseUrl) || baseUrl === '';

// ComfyUI 安装根目录：优先环境变量，其次从 pythonPath 反推
const deriveComfyRoot = () => {
  const envRoot = process.env.BEATDESIGN_COMFYUI_HOME;
  if (envRoot) return envRoot;
  const py = String(config.pythonPath ?? '');
  if (py) {
    // <root>\python_embeded\python.exe
    const idx = py.toLowerCase().indexOf('python_embeded');
    if (idx > 0) return py.slice(0, idx).replace(/[\\/]+$/, '');
  }
  return 'E:\\ComfyUI';
};
const comfyRoot = deriveComfyRoot();
const comfyDir = join(comfyRoot, 'ComfyUI');

// ── 1. 构建产物
const serverEntry = join(ROOT, '.output', 'server', 'index.mjs');
if (existsSync(serverEntry)) {
  add('build', '构建产物', 'pass', '.output/server/index.mjs 存在');
} else {
  add('build', '构建产物', 'fail', '缺少 .output/server/index.mjs', '跑 pnpm build');
}

// ── 2. 依赖
const deps = join(ROOT, 'node_modules');
if (existsSync(deps)) {
  add('deps', 'Node 依赖', 'pass', 'node_modules 存在');
} else {
  add('deps', 'Node 依赖', 'fail', '缺少 node_modules', '跑 pnpm install');
}

// ── 3. 配置
if (existsSync(configPath)) {
  add('config', 'ComfyUI 配置', 'pass', 'data/comfyui.config.json 存在');
} else {
  add('config', 'ComfyUI 配置', 'warn', '缺少 data/comfyui.config.json', '首次启动会自动生成');
}
if (isLocalComfy && config.pythonPath) {
  if (existsSync(String(config.pythonPath))) {
    add('pythonPath', 'ComfyUI 解释器', 'pass', String(config.pythonPath));
  } else {
    add(
      'pythonPath',
      'ComfyUI 解释器',
      'fail',
      `路径不存在：${config.pythonPath}`,
      '改 data/comfyui.config.json 的 pythonPath'
    );
  }
}

// ── 4. ComfyUI 是否在跑
try {
  const res = await fetch(`${baseUrl}/system_stats`, { signal: AbortSignal.timeout(4000) });
  if (res.ok) {
    const stats = await res.json();
    const dev = stats?.devices?.[0];
    const vram = dev ? ` · ${Math.round(dev.vram_total / 1024 ** 3)} GB 显存` : '';
    add('comfyui', 'ComfyUI 服务', 'pass', `${baseUrl} 可访问${vram}`);
  } else {
    add('comfyui', 'ComfyUI 服务', 'fail', `HTTP ${res.status}`, '在服务控制台启动 ComfyUI');
  }
} catch {
  add('comfyui', 'ComfyUI 服务', 'fail', `${baseUrl} 无响应`, '在服务控制台启动 ComfyUI');
}

// ── 5. 模板
const wfDir = join(ROOT, 'data', 'comfyui', 'workflows');
const templates = existsSync(wfDir)
  ? readdirSync(wfDir).filter((f) => f.toLowerCase().endsWith('.json'))
  : [];
add(
  'templates',
  '工作流模板',
  templates.length > 0 ? 'pass' : 'fail',
  `${templates.length} 个`,
  templates.length === 0 ? '检查 data/comfyui/workflows 目录' : undefined
);

// ── 6. 依赖清单
const manifestPath = join(ROOT, 'docs', 'DEPENDENCIES.json');
let manifest = null;
try {
  manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
} catch {
  add(
    'manifest',
    '依赖清单',
    'warn',
    '没有 docs/DEPENDENCIES.json',
    '跑 node scripts/audit-template-deps.mjs 生成'
  );
}

if (manifest) {
  // 清单可能比磁盘上的模板旧
  if (manifest.templateCount !== templates.length) {
    add(
      'manifest-fresh',
      '依赖清单时效',
      'warn',
      `清单记 ${manifest.templateCount} 个模板，磁盘有 ${templates.length} 个`,
      '重新生成：node scripts/audit-template-deps.mjs'
    );
  } else {
    add('manifest-fresh', '依赖清单时效', 'pass', `与磁盘一致（${templates.length} 个模板）`);
  }

  // ── 7. 节点包
  if (!isLocalComfy) {
    add('nodes', '自定义节点包', 'warn', 'ComfyUI 不在本机，无法检查文件', undefined);
  } else {
    const cnDir = join(comfyDir, 'custom_nodes');
    const missingPkgs = (manifest.nodePackages ?? []).filter(
      (p) => !existsSync(join(cnDir, p.name))
    );
    if (missingPkgs.length === 0) {
      add('nodes', '自定义节点包', 'pass', `${manifest.nodePackages.length} / ${manifest.nodePackages.length} 到位`);
    } else {
      const names = missingPkgs.map((p) => p.name);
      add(
        'nodes',
        '自定义节点包',
        'fail',
        `缺 ${missingPkgs.length} 个：${names.slice(0, 4).join('、')}${names.length > 4 ? ' …' : ''}`,
        `ComfyUI/custom_nodes 下补齐：${names.join('、')}`
      );
    }

    // 节点包里的 Python 依赖（粗略：看有没有 requirements.txt 与 __init__.py）
    const broken = (manifest.nodePackages ?? []).filter((p) => {
      const dir = join(cnDir, p.name);
      if (!existsSync(dir)) return false;
      try {
        const entries = readdirSync(dir);
        return !entries.includes('__init__.py') && !entries.includes('nodes.py');
      } catch {
        return true;
      }
    });
    if (broken.length) {
      add(
        'nodes-importable',
        '节点包可加载',
        'warn',
        `${broken.length} 个包目录里没有 __init__.py / nodes.py：${broken.map((p) => p.name).join('、')}`,
        '可能是空目录或复制中断'
      );
    } else if (missingPkgs.length === 0) {
      add('nodes-importable', '节点包可加载', 'pass', '每个包都有入口文件');
    }

    // ── 8. 模型文件
    const index = new Map();
    const dirNames = new Set();
    for (const root of [join(comfyDir, 'models'), join(comfyDir, 'input')]) {
      if (!existsSync(root)) continue;
      const walk = (d) => {
        let entries;
        try {
          entries = readdirSync(d, { withFileTypes: true });
        } catch {
          return;
        }
        for (const e of entries) {
          const p = join(d, e.name);
          if (e.isDirectory()) {
            dirNames.add(e.name);
            walk(p);
          } else if (!index.has(e.name)) {
            index.set(e.name, p);
          }
        }
      };
      walk(root);
    }

    const missingFiles = [];
    let presentFiles = 0;
    let presentBytes = 0;
    for (const f of manifest.files ?? []) {
      const hit = index.get(f.basename);
      if (hit) {
        presentFiles += 1;
        try {
          presentBytes += statSync(hit).size;
        } catch {
          /* 大小读不到不影响存在性判断 */
        }
      } else if (dirNames.has(f.basename)) {
        // 目录型资源（TTS 权重目录）
        presentFiles += 1;
      } else {
        missingFiles.push(f);
      }
    }

    const total = (manifest.files ?? []).length;
    if (missingFiles.length === 0) {
      add('models', '模型文件', 'pass', `${presentFiles} / ${total} 就位 · ${(presentBytes / 1024 ** 3).toFixed(1)} GB`);
    } else {
      const names = missingFiles.map((f) => f.basename);
      add(
        'models',
        '模型文件',
        'fail',
        `${presentFiles} / ${total} 就位，缺 ${missingFiles.length} 个 · ${(presentBytes / 1024 ** 3).toFixed(1)} GB`,
        `缺：${names.slice(0, 3).join('、')}${names.length > 3 ? ` …（共 ${names.length} 个）` : ''}`
      );
    }

    // 缺的模型卡住哪些模板
    if (missingFiles.length) {
      const blocked = new Set();
      for (const f of missingFiles) for (const t of f.templates ?? []) blocked.add(t);
      add(
        'models-impact',
        '受影响模板',
        blocked.size ? 'warn' : 'pass',
        blocked.size ? `${blocked.size} 个模板缺模型：${[...blocked].slice(0, 3).join('、')}${blocked.size > 3 ? ' …' : ''}` : '无'
      );
    }
  }
}

// ── 汇总
const summary = {
  pass: checks.filter((c) => c.status === 'pass').length,
  warn: checks.filter((c) => c.status === 'warn').length,
  fail: checks.filter((c) => c.status === 'fail').length,
};
const ok = summary.fail === 0;

if (JSON_MODE) {
  console.log(
    JSON.stringify(
      { ok, summary, comfyRoot, baseUrl, templates: templates.length, checks },
      null,
      2
    )
  );
} else if (!QUIET) {
  const icon = { pass: '✓', warn: '!', fail: '×' };
  const color = { pass: '\x1b[32m', warn: '\x1b[33m', fail: '\x1b[31m' };
  console.log('');
  console.log('漫客工作台 · 环境自检');
  console.log('='.repeat(56));
  for (const c of checks) {
    console.log(
      `${color[c.status]}${icon[c.status]}\x1b[0m ${c.label.padEnd(14, ' ')} ${c.detail}`
    );
    if (c.hint && c.status !== 'pass') console.log(`  ${' '.repeat(17)}→ ${c.hint}`);
  }
  console.log('='.repeat(56));
  console.log(
    `通过 ${summary.pass}  警告 ${summary.warn}  失败 ${summary.fail}   →  ${ok ? '可以开工' : '先处理失败项'}`
  );
  console.log('');
} else {
  console.log(`${ok ? 'OK' : 'FAIL'} pass=${summary.pass} warn=${summary.warn} fail=${summary.fail}`);
}

process.exit(ok ? 0 : 1);
